const $=id=>document.getElementById(id),fmt=(v,d=0)=>new Intl.NumberFormat('fr-FR',{maximumFractionDigits:d}).format(v);
const data=window.ATLAS_DATA,xy=GazaGeometry.prepare(data.gaza),cities={paris:[48.8566,2.3522],lyon:[45.764,4.8357],marseille:[43.2965,5.3698],bordeaux:[44.8378,-.5792],lille:[50.6292,3.0573],toulouse:[43.6045,1.444],nantes:[47.2184,-1.5536],strasbourg:[48.5734,7.7521],brest:[48.3904,-4.4861],ajaccio:[41.9192,8.7386]};
let center=[2.3522,48.8566],angle=0,level='departements',selected=null,currentFeature,hits=[],population=2226544;
const map=L.map('map',{zoomControl:false,minZoom:4,maxZoom:17}).setView([48.72,2.35],9);
L.control.zoom({position:'topright'}).addTo(map);L.control.scale({imperial:false,position:'bottomleft'}).addTo(map);
let tileFailed=false;const tiles=L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'}).addTo(map);
tiles.on('tileerror',()=>{if(!tileFailed){tileFailed=true;$('status').textContent='Fond de carte indisponible. Les contours et comparaisons restent utilisables.';}});tiles.on('tileload',()=>{if(tileFailed){tileFailed=false;$('status').textContent='';}});
map.createPane('boundaries');map.getPane('boundaries').style.zIndex=350;map.getPane('boundaries').style.pointerEvents='none';
let boundaryLayer=L.geoJSON(data.departements,{pane:'boundaries',style:{color:'#778c98',weight:1,opacity:.6,fillOpacity:0},interactive:false}).addTo(map);
let highlighted=L.geoJSON(null,{pane:'boundaries',style:{color:'#426779',weight:2,fillColor:'#93b7c9',fillOpacity:.13},interactive:false}).addTo(map);
const shape=L.geoJSON(null,{style:{color:'#d15f35',weight:2.5,fillColor:'#ee8158',fillOpacity:.32,className:'gaza-shape'}}).addTo(map);
const icon=(cls,text,size)=>L.divIcon({className:cls,html:text,iconSize:[size,size],iconAnchor:[size/2,size/2]});
const anchor=L.marker([center[1],center[0]],{icon:icon('center-handle','✥',28),draggable:true,title:'Déplacer Gaza',zIndexOffset:1000}).addTo(map);
const rotation=L.marker([center[1],center[0]],{icon:icon('rotate-handle','↻',27),draggable:true,title:'Faire pivoter Gaza',zIndexOffset:1000}).addTo(map);
const arm=L.polyline([],{color:'#20333b',weight:1.5,dashArray:'4 5',interactive:false}).addTo(map);
const label=L.marker([center[1],center[0]],{icon:L.divIcon({className:'gaza-label',html:'GAZA · 365 km²',iconSize:[120,20],iconAnchor:[-20,10]}),interactive:false}).addTo(map);
for(const name of ['departements','regions'])for(const f of data[name].features)f.bbox=turf.bbox(f);
function draw(){currentFeature=GazaGeometry.place(xy,center,angle);shape.clearLayers().addData(currentFeature);anchor.setLatLng([center[1],center[0]]);label.setLatLng([center[1],center[0]]);const a=angle*Math.PI/180,p=GazaGeometry.inverse([25000*Math.sin(a),25000*Math.cos(a)],center);rotation.setLatLng([p[1],p[0]]);arm.setLatLngs([[center[1],center[0]],[p[1],p[0]]]);$('rotation').value=angle;$('angle').textContent=Math.round(angle)+'°';attachDrag();}
function attachDrag(){shape.eachLayer(layer=>{const path=layer.getElement();if(!path)return;path.addEventListener('pointerdown',event=>{if(event.button!==0)return;event.preventDefault();event.stopPropagation();const start=map.mouseEventToLatLng(event),original=[...center],pointer=event.pointerId;map.dragging.disable();const move=e=>{if(e.pointerId!==pointer)return;const p=map.mouseEventToLatLng(e);center=[original[0]+p.lng-start.lng,Math.max(-80,Math.min(80,original[1]+p.lat-start.lat))];draw();};const end=()=>{document.removeEventListener('pointermove',move);document.removeEventListener('pointerup',end);document.removeEventListener('pointercancel',end);map.dragging.enable();compare();};document.addEventListener('pointermove',move);document.addEventListener('pointerup',end);document.addEventListener('pointercancel',end);});});}
function compare(){const b=turf.bbox(currentFeature);hits=data[level].features.filter(f=>{const a=f.bbox;return a[0]<=b[2]&&a[2]>=b[0]&&a[1]<=b[3]&&a[3]>=b[1]&&turf.booleanIntersects(f,currentFeature);});hits.sort((a,b)=>a.properties.nom.localeCompare(b.properties.nom,'fr'));if(!hits.some(f=>f.properties.code===selected))selected=(hits.find(f=>turf.booleanPointInPolygon(turf.point(center),f))??hits[0])?.properties.code;renderComparison();}
function renderComparison(){const f=hits.find(f=>f.properties.code===selected);$('territory-tabs').replaceChildren();highlighted.clearLayers();if(!f){$('territory-name').textContent='Hors des territoires couverts';$('comparison-body').innerHTML='<p class="micro">Placez Gaza sur la France métropolitaine pour comparer les territoires.</p>';return;}highlighted.addData(f);$('territory-name').textContent=f.properties.nom;if(hits.length>1)for(const f of hits){const b=document.createElement('button');b.textContent=f.properties.nom;b.className=f.properties.code===selected?'active':'';b.onclick=()=>{selected=f.properties.code;renderComparison();};$('territory-tabs').append(b);}const s=data.stats[level][selected];if(!s||!s.surface){$('comparison-body').innerHTML='<p>Données non disponibles pour ce territoire.</p>';return;}const ratio=s.surface/365,density=s.population/s.surface;
$('comparison-body').innerHTML=`<div class="metrics"><div class="metric"><strong>${fmt(s.surface)} <span>km²</span></strong><span>${fmt(s.surface*100)} hectares</span></div><div class="metric"><strong>${fmt(s.population)}</strong><span>habitants</span></div><div class="metric"><strong>${fmt(density)}</strong><span>habitants / km²</span></div></div><div class="ratio"><span class="ratio-track"><i style="width:${Math.min(100,365/s.surface*100)}%"></i></span><span>${ratio>=1?`Ce territoire représente <b>${fmt(ratio,1)} fois Gaza</b>.`:`Gaza représente <b>${fmt(1/ratio,1)} fois ce territoire</b>.`} Densité de Gaza : <b>${fmt(population/365/density,1)}×</b> celle du territoire.</span></div>`;}
anchor.on('drag',()=>{const p=anchor.getLatLng();center=[p.lng,Math.max(-80,Math.min(80,p.lat))];draw();});anchor.on('dragend',compare);
rotation.on('drag',()=>{const p=rotation.getLatLng(),v=GazaGeometry.forward([p.lng,p.lat],center);angle=(Math.atan2(v[0],v[1])*180/Math.PI+360)%360;draw();});rotation.on('dragend',compare);
$('rotation').oninput=e=>{angle=Number(e.target.value);draw();};$('rotation').onchange=compare;$('rotate').onclick=()=>{angle=(angle+90)%360;draw();compare();};
function go(city){const p=cities[city];center=[p[1],p[0]];map.setView([p[0]-.13,p[1]],9);draw();compare();}
$('city').onchange=e=>go(e.target.value);$('reset').onclick=()=>{angle=0;$('city').value='paris';go('paris');};$('center').onclick=()=>{const p=map.getCenter();center=[p.lng,p.lat];draw();compare();};$('france').onclick=()=>map.fitBounds([[41.2,-5.3],[51.1,9.7]]);
function setLevel(value){level=value;selected=null;$('dept').setAttribute('aria-pressed',level==='departements');$('region').setAttribute('aria-pressed',level==='regions');boundaryLayer.clearLayers().addData(data[level]);compare();}
$('dept').onclick=()=>setLevel('departements');$('region').onclick=()=>setLevel('regions');
function setPeriod(){population=$('period').value==='2023'?2226544:2130000;$('gaza-pop').textContent=($('period').value==='2025'?'≈ ':'')+fmt(population);$('gaza-density').textContent=fmt(population/365);$('period-note').textContent=$('period').value==='2023'?'PCBS · estimation de mi-2023, avant octobre 2023.':'PCBS · estimation arrondie de fin 2025, pas un bilan définitif.';renderComparison();}
$('period').onchange=setPeriod;$('sources-button').onclick=()=>$('sources').showModal();$('close-sources').onclick=()=>$('sources').close();$('sources').onclick=e=>{if(e.target===$('sources')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}};
anchor.on('add',()=>{});$('map').addEventListener('keydown',e=>{if(e.target!==$('map')&&e.target!==anchor.getElement())return;const changes={ArrowLeft:[-1000,0],ArrowRight:[1000,0],ArrowUp:[0,1000],ArrowDown:[0,-1000]};if(changes[e.key]){e.preventDefault();e.stopPropagation();center=GazaGeometry.inverse(changes[e.key],center);draw();compare();}},true);
draw();compare();setPeriod();new ResizeObserver(()=>map.invalidateSize()).observe($('map'));
window.atlas={place:(lat,lng,rotationAngle=0)=>{if(!Number.isFinite(lat)||!Number.isFinite(lng)||!Number.isFinite(rotationAngle)||lat<-80||lat>80||lng<-180||lng>180)throw new Error('Coordonnées invalides');center=[lng,lat];angle=(rotationAngle%360+360)%360;draw();compare();return {latitude:lat,longitude:lng,angle,areaKm2:turf.area(currentFeature)/1e6,territories:hits.map(f=>f.properties.nom)};},read:()=>({center,angle,level,areaKm2:turf.area(currentFeature)/1e6,territories:hits.map(f=>f.properties.nom)})};
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'place_gaza',title:'Placer Gaza sur la carte',description:'Déplace le contour de Gaza et règle sa rotation, puis retourne les territoires français survolés.',inputSchema:{type:'object',properties:{latitude:{type:'number',minimum:-80,maximum:80},longitude:{type:'number',minimum:-180,maximum:180},rotation:{type:'number'}},required:['latitude','longitude'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>window.atlas.place(input.latitude,input.longitude,input.rotation??0)})).catch(()=>{});}catch{}}

